"""Behavioral tests for the vendored asn1crypto X.509 type definitions."""

import hashlib
from collections import OrderedDict
from datetime import datetime, timezone

import pytest

import jc.utils
from jc.parsers.asn1crypto import jc_global
from jc.parsers.asn1crypto import x509
from jc.parsers.asn1crypto.core import Null, UTF8String
from jc.parsers.asn1crypto.keys import PublicKeyInfo, RSAPublicKey


def _name(common_name='example.com', **attributes):
    values = dict(attributes)
    if common_name is not None:
        values['common_name'] = common_name
    return x509.Name.build(values)


def _public_key_info():
    return PublicKeyInfo({
        'algorithm': {'algorithm': 'rsa'},
        'public_key': RSAPublicKey({'modulus': 3233, 'public_exponent': 17}),
    })


def _extension(name, value, critical=False):
    return x509.Extension({
        'extn_id': name,
        'critical': critical,
        'extn_value': value,
    })


def _certificate(subject=None, issuer=None, extensions=None, serial_number=123456,
                 signature_value=b'\xde\xad\xbe\xef'):
    if subject is None:
        subject = _name()
    if issuer is None:
        issuer = _name()
    tbs = {
        'version': 'v3',
        'serial_number': serial_number,
        'signature': {'algorithm': 'sha256_rsa'},
        'issuer': issuer,
        'validity': {
            'not_before': {'utc_time': '240101000000Z'},
            'not_after': {'utc_time': '300101000000Z'},
        },
        'subject': subject,
        'subject_public_key_info': _public_key_info(),
    }
    if extensions is not None:
        tbs['extensions'] = extensions
    return x509.Certificate({
        'tbs_certificate': tbs,
        'signature_algorithm': {'algorithm': 'sha256_rsa'},
        'signature_value': signature_value,
    })


def _directory_name_type_value(type_name, value):
    return x509.NameTypeAndValue({
        'type': type_name,
        'value': x509.DirectoryString(
            name='utf8_string',
            value=UTF8String(value),
        ),
    })


def _dns_general_name(value):
    return x509.GeneralName(name='dns_name', value=value)


def _uri_general_name(value):
    return x509.GeneralName(name='uniform_resource_identifier', value=value)


def _full_name_distribution_point(url):
    return x509.DistributionPoint({
        'distribution_point': x509.DistributionPointName(
            name='full_name',
            value=x509.GeneralNames([_uri_general_name(url)]),
        ),
    })


def _relative_distribution_point():
    rdn = x509.RelativeDistinguishedName([
        _directory_name_type_value('common_name', 'issuer-relative'),
    ])
    return x509.DistributionPoint({
        'distribution_point': x509.DistributionPointName(
            name='name_relative_to_crl_issuer',
            value=rdn,
        ),
    })


class TestDNSName:
    def test_set_and_equality_are_dns_case_insensitive(self):
        name = x509.DNSName('Example.COM')

        assert name.native == 'Example.COM'
        assert name.contents == b'Example.COM'
        assert name == x509.DNSName('example.com')
        assert name != x509.DNSName('other.example.com')
        assert name != 'Example.COM'

    def test_idna_encoding_and_leading_dot(self):
        international = x509.DNSName('täst.example')
        assert international.contents == b'xn--tst-qla.example'
        assert international.native == 'täst.example'

        leading_dot = x509.DNSName('.Example.COM')
        assert leading_dot.contents == b'.Example.COM'
        assert leading_dot.native == '.Example.COM'
        assert leading_dot != x509.DNSName('Example.COM')

    def test_rejects_non_string_values(self):
        with pytest.raises(TypeError, match='unicode string'):
            x509.DNSName(123)


class TestURI:
    def test_iri_is_encoded_to_uri_but_native_remains_iri(self):
        iri = 'https://例え.テスト/パス'
        uri = x509.URI(iri)

        assert uri.contents == b'https://xn--r8jz45g.xn--zckzah/%E3%83%91%E3%82%B9'
        assert uri.native == iri
        assert uri == x509.URI(
            'https://xn--r8jz45g.xn--zckzah/%E3%83%91%E3%82%B9'
        )
        assert uri != 'https://example.com/'

    def test_spaces_are_percent_encoded(self):
        uri = x509.URI('https://example.com/a b')
        assert uri.contents == b'https://example.com/a%20b'
        assert uri.native == 'https://example.com/a b'

    def test_rejects_non_string_values(self):
        with pytest.raises(TypeError, match='unicode string'):
            x509.URI(123)


class TestEmailAddress:
    def test_idna_hostname_and_host_case_insensitive_equality(self):
        address = x509.EmailAddress('user@täst.example')
        assert address.contents == b'user@xn--tst-qla.example'
        assert address.native == 'user@täst.example'

        assert (
            x509.EmailAddress('User@example.com')
            == x509.EmailAddress('User@example.COM')
        )
        assert (
            x509.EmailAddress('User@example.com')
            != x509.EmailAddress('user@example.com')
        )
        assert x509.EmailAddress('user@example.com') != 'user@example.com'

    def test_invalid_idn_falls_back_to_escaped_ascii_with_warning(self, capsys, monkeypatch):
        monkeypatch.setattr(jc_global, 'quiet', False)
        monkeypatch.setattr(jc.utils, 'CLI_QUIET', False)

        address = x509.EmailAddress.load(b'\x16\x06user@\xff')

        assert address.native == 'user@\\xff'
        captured = capsys.readouterr()
        assert 'Invalid email address found' in captured.err

    def test_rejects_non_string_values(self):
        with pytest.raises(TypeError, match='unicode string'):
            x509.EmailAddress(123)


class TestIPAddress:
    def test_ipv4_ipv6_and_cidr_round_trip(self):
        ipv4 = x509.IPAddress('192.0.2.1')
        assert ipv4.contents == b'\xc0\x00\x02\x01'
        assert ipv4.native == '192.0.2.1'

        ipv6 = x509.IPAddress('2001:db8::1')
        assert ipv6.contents == bytes.fromhex('20010db8000000000000000000000001')
        assert ipv6.native == '2001:db8::1'
        assert ipv6 == x509.IPAddress('2001:0db8:0:0:0:0:0:1')

        cidr = x509.IPAddress('192.0.2.0/24')
        assert cidr.contents == bytes.fromhex('c0000200ffffff00')
        assert cidr.native == '192.0.2.0/24'

        cidr6 = x509.IPAddress('2001:db8::/32')
        assert cidr6.native == '2001:db8::/32'
        assert len(cidr6.contents) == 32

    def test_parse_is_not_supported(self):
        with pytest.raises(ValueError, match='can not be parsed'):
            x509.IPAddress('192.0.2.1').parse()

    @pytest.mark.parametrize(
        'value, message',
        [
            ('192.0.2.0/-1', 'less than 0'),
            ('192.0.2.0/33', 'bigger than 32'),
            ('2001:db8::/129', 'bigger than 128'),
        ],
    )
    def test_invalid_cidr_ranges(self, value, message):
        with pytest.raises(ValueError, match=message):
            x509.IPAddress(value)

    def test_rejects_non_string_values(self):
        with pytest.raises(TypeError, match='unicode string'):
            x509.IPAddress(123)


class TestTeletexString:
    def test_cp1252_and_strict_teletex_context(self):
        encoded = b'\x14\x01\x80'

        assert x509.NotReallyTeletexString.load(encoded).native == '€'

        with x509.strict_teletex():
            assert x509.NotReallyTeletexString._decoding_encoding == 'teletex'
            assert x509.NotReallyTeletexString.load(encoded).native == '\x80'

        assert x509.NotReallyTeletexString._decoding_encoding == 'cp1252'
        assert x509.NotReallyTeletexString.load(encoded).native == '€'

    def test_context_restores_default_after_exception(self):
        with pytest.raises(RuntimeError):
            with x509.strict_teletex():
                raise RuntimeError('boom')

        assert x509.NotReallyTeletexString._decoding_encoding == 'cp1252'


class TestNameTypes:
    def test_name_type_ordering_and_human_friendly_labels(self):
        assert (
            x509.NameType.preferred_ordinal('2.5.4.3')
            == x509.NameType.preferred_ordinal('common_name')
        )
        assert x509.NameType.preferred_ordinal('country_name') < (
            x509.NameType.preferred_ordinal('common_name')
        )
        assert x509.NameType.preferred_ordinal('1.2.3.4') == (
            len(x509.NameType.preferred_order), '1.2.3.4'
        )
        assert x509.NameType('common_name').human_friendly == 'Common Name'
        assert x509.NameType('1.2.3.4').human_friendly == '1.2.3.4'

    def test_prepped_value_normalizes_case_spaces_and_unicode(self):
        padded = _directory_name_type_value('common_name', '  Example   Corp  ')
        canonical = _directory_name_type_value('common_name', 'example corp')
        folded = _directory_name_type_value('common_name', 'EXAMPLE CORP')
        soft_hyphen = _directory_name_type_value('common_name', 'Exam\u00adple Corp')
        sharp_s = _directory_name_type_value('common_name', 'Straße')
        upper_ss = _directory_name_type_value('common_name', 'STRASSE')

        assert padded.prepped_value == ' example  corp '
        assert padded == canonical
        assert folded == canonical
        assert soft_hyphen == canonical
        assert sharp_s == upper_ss
        assert padded != _directory_name_type_value(
            'organization_name', 'example corp'
        )
        assert padded != 'example corp'

    @pytest.mark.parametrize(
        'value, message',
        [
            ('replacement \ufffd', 'replacement character'),
            ('private \ue000', 'private use characters'),
            ('mixed abc\u05d0', 'malformed bidirectional sequence'),
        ],
    )
    def test_prohibited_name_values(self, value, message):
        value_obj = _directory_name_type_value('common_name', value)
        with pytest.raises(ValueError, match=message):
            value_obj.prepped_value


class TestNames:
    def test_build_native_human_friendly_and_hashes(self):
        name = x509.Name.build({
            'common_name': 'example.com',
            'organization_name': 'Example Inc',
            'country_name': 'US',
        })

        assert isinstance(name, x509.Name)
        assert name.native == OrderedDict([
            ('country_name', 'US'),
            ('organization_name', 'Example Inc'),
            ('common_name', 'example.com'),
        ])
        assert name.human_friendly == (
            'Common Name: example.com, Organization: Example Inc, Country: US'
        )
        assert len(name) == 3
        assert name.dump().hex() == (
            '3039310b300906035504061302555331143012060355040a0c0b4578616d706c6520496e63'
            '3114301206035504030c0b6578616d706c652e636f6d'
        )
        assert name.sha1.hex() == '7cf394c22a1c393af20758e5f10a0406bf9a4478'
        assert name.sha256.hex() == (
            '2637dc926eae20e3998e49db8195a7bebdfabbaeff510257eb29bb47d5f66e63'
        )
        assert name != 'example.com'

    def test_equality_uses_prepared_values_and_order_is_significant(self):
        first = x509.Name.build({'common_name': 'Example.COM'})
        second = x509.Name.build({'common_name': ' example.com '})
        third = x509.Name.build({'common_name': 'other.example.com'})

        assert first == second
        assert first.hashable == second.hashable
        assert first != third

        ordered_one = x509.Name.build({
            'common_name': 'example.com',
            'organization_name': 'Example Inc',
        })
        ordered_two = x509.Name.build({
            'organization_name': 'Other Organization',
            'common_name': 'example.com',
        })
        assert ordered_one != ordered_two

    def test_printable_string_build_and_round_trip(self):
        name = x509.Name.build({'common_name': 'Example'}, use_printable=True)

        assert name.dump().hex() == '30123110300e060355040313074578616d706c65'
        assert x509.Name.load(name.dump()) == name

    def test_duplicate_name_values_become_a_list_and_are_humanized(self):
        name = x509.Name(name='', value=x509.RDNSequence([
            x509.RelativeDistinguishedName([
                _directory_name_type_value('common_name', 'first'),
            ]),
            x509.RelativeDistinguishedName([
                _directory_name_type_value('organization_name', 'Org'),
            ]),
            x509.RelativeDistinguishedName([
                _directory_name_type_value('common_name', 'second'),
            ]),
        ]))

        assert name.native == OrderedDict([
            ('common_name', ['first', 'second']),
            ('organization_name', 'Org'),
        ])
        assert name.human_friendly == 'Organization: Org; Common Name: second, first'

    def test_human_friendly_uses_semicolons_when_a_value_contains_a_comma(self):
        name = x509.Name.build({
            'common_name': 'Example, Inc',
            'organization_name': 'Org',
        })
        assert name.human_friendly == 'Common Name: Example, Inc; Organization: Org'


class TestRelativeDistinguishedNames:
    def test_multivalued_rdn_equality_is_order_independent(self):
        first = x509.RelativeDistinguishedName([
            _directory_name_type_value('common_name', 'Example'),
            _directory_name_type_value('organization_name', 'Org'),
        ])
        second = x509.RelativeDistinguishedName([
            _directory_name_type_value('organization_name', 'org'),
            _directory_name_type_value('common_name', 'EXAMPLE'),
        ])

        assert first == second
        assert first.hashable == second.hashable
        assert first != 'not an rdn'
        assert x509.RDNSequence([first]) == x509.RDNSequence([second])
        assert x509.RDNSequence([first]) != 'not an rdn sequence'


class TestGeneralNames:
    def test_sequence_and_general_name_equality(self):
        names = x509.GeneralNames([
            _dns_general_name('Example.com'),
            x509.GeneralName(name='ip_address', value='192.0.2.1'),
        ])

        assert names.native == ['Example.com', '192.0.2.1']
        assert names[0] == _dns_general_name('example.COM')
        assert names[0] != x509.GeneralName(
            name='uniform_resource_identifier',
            value='https://example.com/',
        )
        assert names[0] != x509.GeneralName(
            name='ip_address',
            value='192.0.2.1',
        )

    def test_comparison_of_unsupported_choices_raises(self):
        other = x509.GeneralName(name='other_name', value={
            'type_id': '1.2.3.4',
            'value': UTF8String('other'),
        })
        dns_name = _dns_general_name('example.com')

        with pytest.raises(ValueError, match='other_name'):
            dns_name == other
        with pytest.raises(ValueError, match='other_name'):
            other == dns_name


