class TestCertificateCoreProperties:
    def test_public_properties_and_der_round_trip(self):
        expected_public_key = _public_key_info()
        cert = _certificate(serial_number=123456)

        assert cert.serial_number == 123456
        assert cert.subject.native == OrderedDict([
            ('common_name', 'example.com'),
        ])
        assert cert.issuer.native == OrderedDict([
            ('common_name', 'example.com'),
        ])
        assert cert.public_key.native == expected_public_key.native
        assert cert.signature == b'\xde\xad\xbe\xef'
        assert cert.signature_algo == 'rsassa_pkcs1v15'
        assert cert.hash_algo == 'sha256'
        assert cert.not_valid_before == datetime(
            2024, 1, 1, 0, 0, tzinfo=timezone.utc
        )
        assert cert.not_valid_after == datetime(
            2030, 1, 1, 0, 0, tzinfo=timezone.utc
        )
        assert cert.issuer_serial == cert.issuer.sha256 + b':123456'
        assert cert.self_issued is True
        assert cert.self_signed == 'maybe'
        assert cert.ca is None
        assert cert.max_path_length is None

        loaded = x509.Certificate.load(cert.dump())
        assert loaded.dump() == cert.dump()
        assert loaded.subject == cert.subject
        assert loaded.serial_number == 123456

    def test_hashes_and_fingerprints_are_derived_from_der(self):
        cert = _certificate()

        assert cert.sha1 == hashlib.sha1(cert.dump()).digest()
        assert cert.sha256 == hashlib.sha256(cert.dump()).digest()
        assert cert.sha1_fingerprint == ' '.join(
            '%02X' % byte for byte in cert.sha1
        )
        assert cert.sha256_fingerprint == ' '.join(
            '%02X' % byte for byte in cert.sha256
        )
        assert len(cert.sha1_fingerprint.split(' ')) == 20
        assert len(cert.sha256_fingerprint.split(' ')) == 32


class TestCertificateExtensions:
    def test_extension_values_and_critical_set(self):
        issuer_name = _name('ca.example.com')
        cert = _certificate(extensions=_rich_extensions())

        extensions = cert['tbs_certificate']['extensions']
        assert isinstance(extensions, x509.Extensions)
        assert len(extensions) == 21
        assert cert.critical_extensions == {
            'key_usage',
            'basic_constraints',
            '1.2.3.99',
        }

        assert isinstance(
            cert.private_key_usage_period_value,
            x509.PrivateKeyUsagePeriod,
        )
        assert cert.private_key_usage_period_value['not_before'].native == (
            datetime(2020, 1, 1, tzinfo=timezone.utc)
        )
        assert cert.subject_directory_attributes_value.native == []
        assert cert.key_identifier_value.native == b'\x01'
        assert cert.key_usage_value.native == {
            'digital_signature',
            'key_cert_sign',
        }
        assert cert.subject_alt_name_value.native == [
            'example.com',
            'www.example.com',
        ]
        assert cert.issuer_alt_name_value.native == ['example.com']
        assert cert.basic_constraints_value.native == OrderedDict([
            ('ca', True),
            ('path_len_constraint', 2),
        ])
        assert (
            cert.name_constraints_value['permitted_subtrees'][0]['base'].native
            == 'example.com'
        )
        assert cert.crl_distribution_points_value.native == []
        assert (
            cert.certificate_policies_value[0]['policy_identifier'].native
