        path = tmp_path / "example.toml"
        path.write_bytes(b'title = "example"\n[owner]\nname = "Tom"\n')

        with path.open("rb") as fp:
            assert load(fp) == {"title": "example", "owner": {"name": "Tom"}}

    def test_load_forwards_custom_parse_float(self, tmp_path):
        path = tmp_path / "numbers.toml"
        path.write_bytes(b"small = 0.1\nwhole = 2\n")

        with path.open("rb") as fp:
