        with pytest.raises(TOMLDecodeError):
            loads(src)

    @pytest.mark.parametrize(
        "src",
        [
            "x = { a = 1 }\nx.b = 2",
            "x = { a = [1] }\nx.a.b = 2",
        ],
    )
    def test_inline_table_namespaces_are_immutable(self, src):
        with pytest.raises(TOMLDecodeError, match="immutable namespace"):
            loads(src)


class TestStrings:
    def test_all_supported_single_line_escapes(self):
        src = r'x = "\b\t\n\f\r\"\\"'
        assert loads(src) == {"x": "\b\t\n\f\r\"\\"}

    def test_unicode_escapes(self):
        src = r'x = "A\u00e9\U0001F600"'
        assert loads(src) == {"x": "Aé😀"}

    def test_literal_strings_do_not_process_escapes(self):
        src = r"path = 'C:\Users\nodejs\template'"
        assert loads(src) == {"path": "C:\\Users\\nodejs\\template"}

    def test_multiline_basic_string_and_line_ending_backslash(self):
        src = 'x = """The quick brown \\\n\n  fox jumps over \\\n    the lazy dog."""'
        assert loads(src) == {"x": "The quick brown fox jumps over the lazy dog."}

    def test_multiline_basic_string_preserves_internal_quotes_and_newlines(self):
        src = 'x = """Here are two quotation marks: "". Simple enough."""'
        assert loads(src) == {
            "x": 'Here are two quotation marks: "". Simple enough.'
        }

    def test_multiline_strings_trim_only_the_first_newline(self):
        basic = loads('x = """\nfoo\nbar\n"""')
        literal = loads("x = '''\nfoo\nbar\n'''")
        assert basic == {"x": "foo\nbar\n"}
        assert literal == {"x": "foo\nbar\n"}

    def test_multiline_literal_string_keeps_backslashes_and_apostrophe(self):
        src = "x = '''I [dw]on't need \\d{2} apples'''"
        assert loads(src) == {"x": "I [dw]on't need \\d{2} apples"}

    @pytest.mark.parametrize(
        ("src", "expected"),
        [
            ('x = ' + '"' * 7, {'x': '"'}),
            ('x = ' + '"' * 8, {'x': '""'}),
            ("x = " + "'" * 7, {"x": "'"}),
            ("x = " + "'" * 8, {"x": "''"}),
        ],
    )
    def test_multiline_quotes_can_end_with_one_or_two_extra_delimiters(
        self, src, expected
    ):
        assert loads(src) == expected

    @pytest.mark.parametrize(
        "src",
        [
            r'x = "\q"',
            r'x = "\u12G4"',
            r'x = "\u123"',
            r'x = "\uD800"',
            r'x = "\U00110000"',
            'x = "unterminated',
            'x = "line\nbreak"',
            'x = "control \x01"',
            "x = 'control \x01'",
        ],
    )
    def test_invalid_or_unterminated_strings_are_rejected(self, src):
        with pytest.raises(TOMLDecodeError):
            loads(src)


class TestNumbers:
    def test_integer_forms(self):
        src = """
zero = 0
positive = +99
negative = -17
grouped = 1_000_000
hex = 0xDEAD_BEEF
oct = 0o755
binary = 0b1101_0010
"""
        assert loads(src) == {
            "zero": 0,
            "positive": 99,
            "negative": -17,
            "grouped": 1_000_000,
            "hex": 0xDEADBEEF,
            "oct": 0o755,
            "binary": 0b11010010,
        }

    def test_float_forms(self):
        src = """
simple = 3.1415
negative = -0.01
exponent = 5e+22
positive_exponent = 1e06
short_exponent = -2E-2
grouped = 224_617.445_991_228
"""
        expected = {
            "simple": 3.1415,
            "negative": -0.01,
            "exponent": 5e22,
            "positive_exponent": 1e6,
            "short_exponent": -0.02,
            "grouped": 224617.445991228,
        }
        assert loads(src) == expected

    def test_special_float_values(self):
        result = loads("pos_inf = inf\nneg_inf = -inf\npos_nan = +nan\nneg_nan = -nan")
        assert math.isinf(result["pos_inf"]) and result["pos_inf"] > 0
        assert math.isinf(result["neg_inf"]) and result["neg_inf"] < 0
        assert math.isnan(result["pos_nan"])
        assert math.isnan(result["neg_nan"])

    @pytest.mark.parametrize(
        "src",
        [
            "x = 01",
            "x = .5",
            "x = 1.",
            "x = 1__0",
            "x = 0x",
            "x = +",
            "x = Inf",
            "x = 0b102",
        ],
    )
    def test_malformed_numbers_are_rejected(self, src):
        with pytest.raises(TOMLDecodeError):
            loads(src)

    def test_custom_parse_float_receives_original_float_text(self):
        calls = []

        def parse_float(text):
            calls.append(text)
            return ("float", text)

        result = loads(
            "integer = 1\nsimple = 1.5\ngrouped = 1_000.25\n"
            "infinity = inf\nnegative_nan = -nan",
            parse_float=parse_float,
        )

        assert result == {
            "integer": 1,
            "simple": ("float", "1.5"),
            "grouped": ("float", "1_000.25"),
            "infinity": ("float", "inf"),
            "negative_nan": ("float", "-nan"),
        }
        assert calls == ["1.5", "1_000.25", "inf", "-nan"]

    def test_parse_float_is_not_called_for_integers(self):
        def unexpected_parse_float(text):
            pytest.fail(f"parse_float called for integer {text!r}")

        assert loads("small = 1\nlarge = 0xFF", parse_float=unexpected_parse_float) == {
            "small": 1,
            "large": 255,
        }

    @pytest.mark.parametrize("illegal", [{}, [], {"nested": 1}, [1]])
    def test_parse_float_may_not_return_containers(self, illegal):
        with pytest.raises(ValueError, match="parse_float must not return dicts or lists"):
            loads("x = 1.0", parse_float=lambda _text: illegal)

    def test_parse_float_exceptions_propagate(self):
        class CustomError(Exception):
            pass

        def broken_parse_float(text):
            raise CustomError(text)

        with pytest.raises(CustomError, match="2.5"):
            loads("x = 2.5", parse_float=broken_parse_float)


class TestDatesAndTimes:
    def test_date_datetime_and_local_time_values(self):
        src = """
date = 1979-05-27
local_datetime = 1979-05-27T07:32:00
space_datetime = 1979-05-27 07:32:00
local_time = 07:32:00.123456789
"""
        assert loads(src) == {
            "date": date(1979, 5, 27),
            "local_datetime": datetime(1979, 5, 27, 7, 32),
            "space_datetime": datetime(1979, 5, 27, 7, 32),
            "local_time": time(7, 32, 0, 123456),
        }

    def test_utc_and_numeric_offsets(self):
        src = """
utc = 1979-05-27T07:32:00Z
lowercase_utc = 1979-05-27t07:32:00z
minus_offset = 1979-05-27T07:32:00-07:00
plus_offset = 1979-05-27T07:32:00+05:30
"""
        result = loads(src)
        assert result["utc"] == datetime(1979, 5, 27, 7, 32, tzinfo=timezone.utc)
        assert result["lowercase_utc"] == datetime(
            1979, 5, 27, 7, 32, tzinfo=timezone.utc
        )
        assert result["minus_offset"] == datetime(
            1979,
            5,
            27,
            7,
            32,
            tzinfo=timezone(timedelta(hours=-7)),
        )
        assert result["plus_offset"] == datetime(
            1979,
            5,
            27,
            7,
            32,
            tzinfo=timezone(timedelta(hours=5, minutes=30)),
        )

    def test_datetime_fraction_is_truncated_to_microseconds(self):
        assert loads("x = 1979-05-27T07:32:00.9999999Z") == {
            "x": datetime(1979, 5, 27, 7, 32, 0, 999999, tzinfo=timezone.utc)
        }

    @pytest.mark.parametrize(
        "src",
        [
            "x = 1979-02-30",
            "x = 1979-13-01",
            "x = 24:00:00",
            "x = 1979-05-27T07:32:00+24:00",
        ],
    )
    def test_invalid_dates_and_times_are_rejected(self, src):
        with pytest.raises(TOMLDecodeError):
            loads(src)


class TestErrors:
    def test_decode_error_is_a_value_error(self):
        assert issubclass(TOMLDecodeError, ValueError)
        with pytest.raises(ValueError):
            loads("x = ?")

    @pytest.mark.parametrize(
        ("src", "message"),
        [
            ("x = ?", "Invalid value (at line 1, column 5)"),
            ("a = 1\nb = ?", "Invalid value (at line 2, column 5)"),
            ("x = [1,", "Invalid value (at end of document)"),
            ('x = "unterminated', "Unterminated string (at end of document)"),
        ],
    )
    def test_error_messages_report_source_coordinates(self, src, message):
        with pytest.raises(TOMLDecodeError) as exc_info:
            loads(src)
        assert str(exc_info.value) == message

    def test_illegal_comment_character_is_reported_at_its_location(self):
        with pytest.raises(TOMLDecodeError) as exc_info:
            loads("# bad \x01 comment\nx = 1")
        assert "Found invalid character '\\x01'" in str(exc_info.value)
        assert "line 1, column 7" in str(exc_info.value)


class TestParserStateHelpers:
    def test_flags_can_be_set_locally_and_recursively(self):
        flags = Flags()
        assert flags.is_((), Flags.FROZEN) is False

        flags.set(("a", "b"), Flags.FROZEN, recursive=False)
        assert flags.is_(("a", "b"), Flags.FROZEN) is True
        assert flags.is_(("a", "b", "c"), Flags.FROZEN) is False

        flags.set(("a",), Flags.EXPLICIT_NEST, recursive=True)
        assert flags.is_(("a", "new"), Flags.EXPLICIT_NEST) is True
        assert flags.is_(("a", "b"), Flags.EXPLICIT_NEST) is True

    def test_pending_flags_are_only_applied_after_finalization(self):
        flags = Flags()
        flags.add_pending(("table",), Flags.EXPLICIT_NEST)
        assert flags.is_(("table",), Flags.EXPLICIT_NEST) is False

        flags.finalize_pending()
        assert flags.is_(("table",), Flags.EXPLICIT_NEST) is True
        # finalization is idempotent and clears the pending collection
        flags.finalize_pending()
        assert flags.is_(("table",), Flags.EXPLICIT_NEST) is True

    def test_unset_all_removes_a_namespace_safely(self):
        flags = Flags()
        flags.set(("a", "b"), Flags.EXPLICIT_NEST, recursive=True)
        assert flags.is_(("a", "b"), Flags.EXPLICIT_NEST) is True

        flags.unset_all(("a",))
        assert flags.is_(("a", "b"), Flags.EXPLICIT_NEST) is False
        # Removing a missing namespace is a no-op.
        flags.unset_all(("missing", "branch"))

    def test_nested_dict_creation_append_and_list_access(self):
        nested = NestedDict()
        leaf = nested.get_or_create_nest(("a", "b"))
        leaf["value"] = 1

        nested.append_nest_to_list(("a", "items"))
        nested.append_nest_to_list(("a", "items"))
        assert nested.dict == {
            "a": {"b": {"value": 1}, "items": [{}, {}]}
        }

        latest = nested.get_or_create_nest(("a", "items"))
        latest["name"] = "second"
        assert nested.dict["a"]["items"] == [{}, {"name": "second"}]

    def test_nested_dict_reports_container_conflicts(self):
        nested = NestedDict()
        nested.dict["scalar"] = 1
        nested.dict["items"] = []

        with pytest.raises(KeyError, match="no nest behind this key"):
            nested.get_or_create_nest(("scalar", "child"))

        with pytest.raises(KeyError, match="no nest behind this key"):
            nested.get_or_create_nest(("items",), access_lists=False)

        nested.dict["not_a_list"] = {}
        with pytest.raises(KeyError, match="object other than list"):
            nested.append_nest_to_list(("not_a_list",))
